import assert from 'node:assert/strict';import {VoxelWorld} from '../rules.js';
let g=new VoxelWorld();const y=g.top(2,0)-.5,n=g.blocks.size;assert(g.edit(2,y,0,false));assert.equal(g.blocks.size,n-1);assert(g.edit(2,y,0,true));assert.equal(g.blocks.size,n);assert.equal(g.edit(0,0,0,false),false,'Bedrock protected');assert.equal(g.edit(40,8,0,true),false,'Reach bounded');const saved=g.save(),restored=new VoxelWorld();assert(restored.load(saved));assert.equal(restored.blocks.size,g.blocks.size);assert.equal(restored.edits,g.edits);assert.equal(restored.load('{"version":1,"blocks":[["1000,0,0",1]]}'),false);assert.equal(restored.load('bad data'),false);
for(let i=0;i<300;i++)g.update(1/60);assert(g.player.ground);assert(Number.isFinite(g.player.y));g.player.y=-20;g.update(.02);assert(g.player.y>0);for(let i=0;i<5;i++){const[x,z]=g.crystals[i];Object.assign(g.player,{x,z,y:g.top(x,z)+.1});g.update(.001)}assert(g.completed);console.log('Voxel Trails: mine/place, reach limits, protected floor, save/load validation, gravity, respawn and crystal objective passed.');
